using Microsoft.UI.Xaml.Markup;
using Microsoft.UI.Xaml.Media;

namespace Campus.Desktop.Design.Icons;

/// <summary>One drawing: path data on the 24×24 grid, and whether it is filled or stroked.</summary>
public readonly record struct IconGlyph(Geometry Geometry, bool IsFilled);

/// <summary>
/// Every Campus symbol, authored as path data on a shared 24×24 grid with a 2-unit optical
/// margin. Stroked icons carry no thickness of their own — <see cref="CampusIcon"/> supplies it
/// from the requested weight and size, which is what lets one definition serve 12px and 48px.
/// </summary>
public static class IconRegistry
{
    public const double GridSize = 24.0;

    public static IconGlyph Resolve(string symbol, IconVariant variant = IconVariant.Outline)
    {
        if (variant == IconVariant.Filled)
        {
            var filledName = symbol + ".fill";
            if (Filled.ContainsKey(filledName)) return new IconGlyph(Parse(Filled[filledName]), true);
            if (Filled.ContainsKey(symbol)) return new IconGlyph(Parse(Filled[symbol]), true);
        }

        if (Filled.TryGetValue(symbol, out var filledData))
            return new IconGlyph(Parse(filledData), true);

        if (Stroked.TryGetValue(symbol, out var data))
            return new IconGlyph(Parse(data), false);

        // An unknown symbol shows the placeholder rather than nothing, so the gap is visible
        // during development instead of silently shipping a blank button.
        return new IconGlyph(Parse(Stroked["file.unknown"]), false);
    }

    public static bool Contains(string symbol) => Stroked.ContainsKey(symbol) || Filled.ContainsKey(symbol);

    public static IEnumerable<string> AllSymbols => Stroked.Keys.Concat(Filled.Keys).Distinct().Order();

    /// <summary>
    /// Parses path data into a fresh Geometry every time. A Geometry can belong to exactly one
    /// Path, so caching and handing the same instance to two icons throws — the parse is cheap
    /// enough that not caching is the right trade.
    /// </summary>
    private static Geometry Parse(string data)
        => (Geometry)XamlBindingHelper.ConvertValue(typeof(Geometry), data);

